// netlify/functions/team-content.js  (generated by the guide builder; do not edit by hand)
// Staff-only. Returns the team guide / training only to a valid POTENT staff login.
var crypto = require("crypto");
var CONTENT = {"team":[{"id":"start","title":"Start here","roles":["owner","dispatch","dispatcher","driver"],"html":"<p>POTENT is a Georgia direct carrier. One 16 ft box truck, one clear price, no hidden fees. We move what is in and move what is out: delivery, freight, event drop-off, junk removal, cleanouts and recurring routes.</p>\n<div class=\"grid\"><div class=\"card\"><h3>We do</h3><ul class=\"chk\"><li>Pickup, loading, transport, ground-level drop-off</li><li>Commercial FFE and freight</li><li>Junk removal and property cleanouts</li><li>Recurring commercial routes</li></ul></div><div class=\"card\"><h3>We never</h3><ul class=\"chk no\"><li>White-glove service</li><li>Stairs beyond 1 flight</li><li>Furniture assembly or installation</li><li>Hazardous materials</li></ul></div></div>\n<div class=\"note\"><b>Standard:</b> when someone hangs up after talking to POTENT, they should think it was one of the most professional calls they have had with a transportation company.</div>"},{"id":"rules","title":"The rules","roles":["owner","dispatch","dispatcher","driver"],"html":"<h3>Zero tolerance. Immediate termination.</h3><ul class=\"chk no\"><li>Sharing your login. Your login is your name on everything.</li><li>Sharing company data: customers, pricing, leads. Nothing leaves.</li><li>Discussing other employees' pay.</li><li>Side jobs using company equipment or contacts.</li><li>Impaired driving. No weed, no alcohol, no intoxicating substance before or while driving for POTENT. If you are not fit to drive, do not drive and tell management.</li></ul>\n<h3>Required every day</h3><ul class=\"chk\"><li>Log every interaction: calls, status updates, fuel. If it is not in the app, it did not happen.</li><li>Keep job statuses current.</li><li>Answer the Owner within 15 minutes in business hours.</li><li>Flag problems immediately. A problem reported early is solved. Hidden, it doubles.</li></ul>\n<h3>Escalation</h3><p><b>Level 1</b> you handle it. <b>Level 2</b> manager: pricing exceptions, disputes, major delays. <b>Level 3</b> Owner immediately: accident, injury, freight loss, legal threat, insurance or compliance issue. When in doubt, escalate. People first, freight second, customer informed, Owner informed, everything documented.</p>\n<p class=\"small\">POTENT OS, the leads database, the pricing system and all company materials are protected intellectual property of POTENT PRÄDƏKT®.</p>"},{"id":"quote","title":"Taking a quote on the phone","roles":["owner","dispatch","dispatcher"],"html":"<ol class=\"steps\"><li><b>Set the pricing tier first.</b> Standard for new customers. Family/Loyalty only for repeat customers and referrals. Never start at the floor.</li>\n<li><b>Name, phone, service type.</b></li><li><b>Addresses: street, city, state.</b> The app measures the real road miles.</li>\n<li><b>Speed, add-ons, payment.</b> Cash is 10% off automatically. Card is charged at booking.</li>\n<li><b>Photos and measurements.</b> Required. No photos, no measurements, no booking.</li>\n<li><b>Read the live total to the customer.</b> Say the exact number on screen.</li>\n<li><b>Check the Profit Guard card.</b> Green means the job covers its share of the bills. Red means review before booking.</li>\n<li><b>Book it, or save as Pending</b> (cleanouts and anything the Owner must review).</li></ol>\n<h3>Tiers</h3><div class=\"tbl\"><table><tr><th>Tier</th><th>Off</th><th>When</th></tr><tr><td>💛 Standard</td><td>0%</td><td>Full rate — all customers</td></tr><tr><td>👨‍👩‍👧 Family / Loyalty</td><td>15%</td><td>15% off — repeat customers &amp; referrals</td></tr><tr><td>🤝 Lowest</td><td>20%</td><td>20% off — absolute floor, no further negotiation</td></tr></table></div><p class=\"small\">The lowest tier is only to close a deal, and you tell the Owner first.</p>\n<h3>Zone prices</h3><div class=\"tbl\"><table><tr><th>Service</th><th class=\"n\">Local 0-50</th><th class=\"n\">Regional 51-150</th><th class=\"n\">Long 150+</th></tr>\n<tr><td>Delivery</td><td class=\"n\">$400</td><td class=\"n\">$750</td><td class=\"n\">$1,500</td></tr><tr><td>Freight</td><td class=\"n\">$400</td><td class=\"n\">$750</td><td class=\"n\">$1,500</td></tr><tr><td>Discreet</td><td class=\"n\">$500</td><td class=\"n\">$900</td><td class=\"n\">$1,800</td></tr></table></div>\n<p>Speeds: Scheduled = base. Same-Day = $25 less. Rush = $100 more. Single item: $250 / $225 / $350. Helper +$100, extra stop +$40. Event: $1,000 flat under 150 round-trip miles, then +$1 per mile.</p>"},{"id":"junk","title":"Junk removal quoting","roles":["owner","dispatch","dispatcher"],"html":"<div class=\"tbl\"><table><tr><th>Load</th><th class=\"n\">Price</th></tr><tr><td>Single Item / Minimum<div class=\"small\">One item or a small pile</div></td><td class=\"n\">$179</td></tr><tr><td>Quarter Load<div class=\"small\">A few items — couch, small cleanout</div></td><td class=\"n\">$250</td></tr><tr><td>Half Load<div class=\"small\">Bedroom set, multiple appliances</div></td><td class=\"n\">$350–$400</td></tr><tr><td>Three-Quarter Load<div class=\"small\">Garage or large room cleanout</div></td><td class=\"n\">$500–$600</td></tr><tr><td>Full Load<div class=\"small\">Full 16ft truck — biggest single trip</div></td><td class=\"n\">$750–$850</td></tr></table></div>\n<h3>Heavy items: they pay for their weight</h3><p>Ask about every heavy item and get the real weight. We never absorb dump weight. Enter each item and its weight in the heavy picker. The charge is a handling fee plus 3x the dump cost of that weight. The rule is never below 2x.</p>\n<div class=\"tbl\"><table><tr><td>Gun safe (small) <span class=\"small\">(starting weight 250 lbs, change it to the real one)</span></td><td class=\"n\">about +$100 each</td></tr><tr><td>Gun safe (large) <span class=\"small\">(starting weight 750 lbs, change it to the real one)</span></td><td class=\"n\">about +$374 each</td></tr><tr><td>Upright piano <span class=\"small\">(starting weight 450 lbs, change it to the real one)</span></td><td class=\"n\">about +$195 each</td></tr><tr><td>Baby grand piano <span class=\"small\">(starting weight 650 lbs, change it to the real one)</span></td><td class=\"n\">about +$364 each</td></tr><tr><td>Hot tub / spa <span class=\"small\">(starting weight 800 lbs, change it to the real one)</span></td><td class=\"n\">about +$379 each</td></tr><tr><td>Slate pool table <span class=\"small\">(starting weight 900 lbs, change it to the real one)</span></td><td class=\"n\">about +$389 each</td></tr><tr><td>Treadmill / elliptical <span class=\"small\">(starting weight 250 lbs, change it to the real one)</span></td><td class=\"n\">about +$100 each</td></tr><tr><td>Weight bench + plates <span class=\"small\">(starting weight 400 lbs, change it to the real one)</span></td><td class=\"n\">about +$190 each</td></tr><tr><td>Refrigerator / freezer <span class=\"small\">(starting weight 250 lbs, change it to the real one)</span></td><td class=\"n\">about +$100 each</td></tr><tr><td>Washer <span class=\"small\">(starting weight 175 lbs, change it to the real one)</span></td><td class=\"n\">about +$92 each</td></tr><tr><td>Dryer <span class=\"small\">(starting weight 130 lbs, change it to the real one)</span></td><td class=\"n\">about +$53 each</td></tr><tr><td>Stove / range <span class=\"small\">(starting weight 200 lbs, change it to the real one)</span></td><td class=\"n\">about +$95 each</td></tr><tr><td>Water heater <span class=\"small\">(starting weight 130 lbs, change it to the real one)</span></td><td class=\"n\">about +$53 each</td></tr><tr><td>Sleeper sofa <span class=\"small\">(starting weight 250 lbs, change it to the real one)</span></td><td class=\"n\">about +$100 each</td></tr><tr><td>Filing cabinet (4 drawer) <span class=\"small\">(starting weight 120 lbs, change it to the real one)</span></td><td class=\"n\">about +$52 each</td></tr><tr><td>Large cabinet / armoire <span class=\"small\">(starting weight 300 lbs, change it to the real one)</span></td><td class=\"n\">about +$105 each</td></tr><tr><td>Loose heavy material (concrete, dirt, brick, tile, shingles, rock)</td><td class=\"n\">$0.15/lb ($0.19 construction)</td></tr></table></div>\n<p class=\"small\">One trip carries 4,300 lbs of junk (about 25 cubic yards). Over that, the app shows how many trips it needs (each extra trip $600) and a dumpster option. Three or more trips, or more than about 8600 lbs, means quote a dumpster. The cash discount never applies to the heavy charge.</p>\n<h3>Dumpsters for big jobs</h3><p>We rent roll-offs from a vendor and charge 1.5x their price. Starting prices: 10-yd $570 (1.5 t incl) · 15-yd $610 (2 t incl) · 20-yd $705 (2.75 t incl) · 30-yd $850 (3 t incl) · 40-yd $1,045 (4 t incl). Extra weight about $128 per ton. The Vendors tab keeps the real vendor prices; confirm them by phone before you quote. Use \"Estimate from photos\" to get the cubic yards and weight.</p>\n<h3>Special disposal items</h3><p>Mattress +$30 · Box Spring +$30 · Tire, 16\" or smaller (off rim) +$6 · Tire, larger than 16\" (off rim) +$30 · Tire (on rim, any size) +$48 · Refrigerator / Freezer (refrigerant) +$45 · AC Unit (refrigerant) +$45 · TV / Monitor (e-waste) +$45 · Paint Can (per gallon) +$15 · Propane Tank, standard +$45 · Hot Tub / Piano (special handling) +$450</p>\n<p>Extra worker $40/hr. Each extra full truckload $600.</p>"},{"id":"guard","title":"Profit Guard: reading the card","roles":["owner","dispatch","dispatcher"],"html":"<p>Every quote shows the same simple check:</p>\n<div class=\"card\"><p><b>Miles</b> = base to pickup + pickup to drop-off + drop-off back to base (Conyers is the base).<br><b>Gas</b> = total miles × the gas rate per mile.<br><b>Profit</b> = price − gas.<br><b>Needed per job</b> = monthly bills ÷ (jobs per week × 4.33).<br><b>Time</b> = drive time + (planned stops × minutes per stop). Stops are gas, bathroom and food.<br><b>Profit per hour</b> = profit ÷ total time.</p></div>\n<ul class=\"chk\"><li><b>Green, covers bills:</b> the job pays its share. Book it.</li><li><b>Red, short by $X:</b> do not book as is. Raise the price, add a service, combine it with another job, or decline.</li><li><b>Booking review required:</b> an address could not be verified. The app will not guess miles. Fix the address.</li><li>For junk jobs, set the dump address once in the card's ⚙ settings so the loaded miles are counted.</li></ul>\n<p class=\"small\">The owner sets the gas rate, monthly bills, jobs per week, stops and minutes per stop in ⚙ settings. Gas rate comes from the last job: type its gas cost and miles, then tap Set gas rate (gas cost ÷ miles).</p>"},{"id":"portal","title":"Customer portal, web bookings and repeat requests","roles":["owner","dispatch","dispatcher"],"html":"<ul class=\"chk\"><li><b>Customers sign in at the portal</b> (the My Jobs page) with the email they booked with. They see only their own jobs, completion photos, their active rate card and their properties.</li><li><b>Web bookings arrive on their own.</b> Jobs customers book online appear in your job list within two minutes of being signed in, with a note at the top. Nothing to enter by hand.</li><li><b>Repeat this job:</b> the customer picks a date and sends a request. It arrives as <b>Pending Quote</b> with the note REPEAT REQUEST. Confirm the date and price with the customer before you confirm the job.</li><li><b>Payments are checked with Stripe.</b> A job is marked paid only after the server confirms the payment with Stripe. If a customer says they paid and the job is not marked paid, check Stripe first.</li><li><b>Repeat jobs on a schedule:</b> in Growth Tools > Repeat jobs, set how often and the next date. Tap Create due jobs and each date becomes its own job.</li></ul>"},{"id":"growth","title":"Growth Tools: accounts, rate cards, zones, repeat jobs","roles":["owner","dispatch","dispatcher"],"html":"<p>Open <b>More &gt; Money &gt; Growth Tools</b>.</p><ul class=\"chk\"><li><b>Accounts:</b> every customer ranked by revenue, with profit per job after gas. Tap one to see its jobs. Red means it averages less than the needed-per-job figure.</li><li><b>Insights:</b> averages from real jobs (revenue per job, per mile, per hour, loading and driving times, margin after gas, how often scope changes). Information only; it never changes a price or a limit.</li><li><b>Alerts:</b> today's jobs with no driver, quotes sitting untouched, low-profit accounts, customers who stopped booking.</li><li><b>Rate cards:</b> named price lists. An active card is never edited. Make a new version, then activate it; the old one is retired and kept on record.</li><li><b>Zones:</b> distance bands from the base with a surcharge and rush multiplier. Check any address to see its zone.</li><li><b>Repeat jobs:</b> save a standing job once, then tap Create job.</li></ul>"},{"id":"jobs","title":"Running a job: clock, photos and scope changes","roles":["owner","dispatch","dispatcher","driver"],"html":"<h3>Job clock</h3><p>Open the job, then tap each stage when it happens: <b>Arrived, Loading started, Loading finished, Departed, Arrived at drop-off, Unloading started, Unloading finished, Job complete.</b> The app works out waiting, loading, driving and unloading times. Events cannot be edited or deleted, so tap them honestly and on time.</p>\n<h3>Problems</h3><p>Tap the red problem button when it happens: Waiting, Customer not ready, Access problem, Damage, Disposal issue, Other. Add a short note.</p>\n<h3>Photos (every job)</h3><ul class=\"chk\"><li>Arrival and the pickup area</li><li>Before loading, and the loaded truck</li><li>Anything different from the booking</li><li>Delivery, and completion</li><li>Container or disposal paperwork when used</li></ul>\n<h3>Scope difference: the rule</h3><div class=\"note warn\"><b>Stop. Do not change the price yourself.</b></div>\n<ol class=\"steps\"><li>Take photos.</li><li>In the job, tap <b>Report scope difference</b>: pick the type (more items, more pallets, higher weight, larger size, additional stop, customer not ready, access problem, load does not fit, different material, additional disposal), what was booked, what is really there.</li><li>Pause until the office sets a revised total and the customer authorizes it by phone or text.</li><li>If the customer declines, the job continues at the original scope and price.</li></ol>"},{"id":"driver","title":"Driver day","roles":["owner","dispatch","dispatcher","driver"],"html":"<h3>Before every job</h3><ul class=\"chk\"><li>Check active jobs in the Driver App</li><li>Confirm pickup address and customer phone</li><li>Vehicle inspection before you drive</li><li>Status to En Route when you leave. Call the customer when you are 10 minutes out.</li></ul>\n<h3>At pickup</h3><ul class=\"chk\"><li>Status Arrived. Tap Arrived on the job clock.</li><li>Photograph the BOL and the load before loading</li><li>Confirm freight, quantity and condition. Check weight against the 4,500 lb limit.</li><li>In Transit when loaded and leaving.</li></ul>\n<h3>At delivery</h3><ul class=\"chk\"><li>Delivered. Photograph proof of delivery (the app will not mark Delivered without a photo).</li><li>Cash jobs: collect payment before you leave. Cards and cash only, no checks.</li><li>Report any damage to the Owner before leaving the site.</li></ul>\n<h3>Fuel: every fill-up, no exceptions</h3><p>Tap Log Fuel, enter the state, gallons and price per gallon. It feeds the IFTA quarterly tax report.</p>\n<h3>Emergencies</h3><p><b>Breakdown:</b> get somewhere safe, tell the Owner, tell the customer, protect the freight. <b>Accident:</b> stop, check injuries, call 911 if needed, call the Owner before moving the vehicle, do not admit fault. <b>Wrong address:</b> stop and verify through the Owner.</p>"},{"id":"vendors","title":"Vendors, containers and disposal","roles":["owner","dispatch","dispatcher"],"html":"<p>Open <b>Fleet → Vendors &amp; Disposal</b>. Containers are rented, not owned. Costs here are never shown to customers.</p>\n<ul class=\"chk\"><li><b>VERIFIED</b>: prices and availability confirmed in the last 30 days.</li><li><b>NEEDS CONFIRMATION</b>: call before you promise anything. The app flips a vendor to this automatically after 30 days.</li><li><b>INACTIVE</b>: do not use.</li></ul>\n<p>After you call and confirm, tap <b>Verified today</b>. Use the one-tap Call button. Do not pick a vendor on lowest cost alone: check size, included tonnage, overage, delivery time and reliability.</p>"},{"id":"exceptions","title":"Cancellations, claims and exceptions","roles":["owner","dispatch","dispatcher","driver"],"html":"<div class=\"tbl\"><table><tr><td><b>Same-Day / Urgent</b></td><td>FINAL — no cancellation once confirmed. Non-refundable.</td></tr><tr><td><b>Under 24 hours</b></td><td>Dispatch fee ($100) retained. Balance refunded.</td></tr><tr><td><b>24-48 hours</b></td><td>50% cancellation fee applies.</td></tr><tr><td><b>48+ hours</b></td><td>Free cancellation. Full refund or credit.</td></tr></table></div>\n<p>Claims on a completed job must be reported in writing within 7 days. Customer not ready, access problem, load does not fit, different material: log it on the job clock, take photos, and report the scope difference if it changes the work.</p>"},{"id":"eod","title":"End of day","roles":["owner","dispatch","dispatcher","driver"],"html":"<ul class=\"chk\"><li>No unanswered customer request</li><li>No unassigned job</li><li>No missing payment status</li><li>No lead without a next action</li><li>Every fuel fill-up logged</li><li>Every job's clock finished and photos attached</li></ul>"},{"id":"map","title":"Where things are in the app","roles":["owner","dispatch","dispatcher","driver"],"html":"<div class=\"tbl\"><table><tr><td>Quote and book</td><td>Quick Quote / Quote tab</td></tr><tr><td>Junk jobs</td><td>New Junk Job, Junk Driver Jobs</td></tr><tr><td>Job clock, scope difference, route legs</td><td>Open any job</td></tr><tr><td>Vendors and disposal</td><td>More → Fleet → Vendors &amp; Disposal</td></tr><tr><td>Fuel log, navigation, SOS</td><td>Driver App</td></tr><tr><td>Leads</td><td>Leads tab</td></tr></table></div><p class=\"small\">Login: potentoperations.netlify.app, then your assigned name and password. Need credentials? Call the Owner at (770) 648-4228.</p>"}],"training":[{"id":"sales","title":"Selling logistics the POTENT way","roles":["owner","dispatch","dispatcher"],"html":"<h3>The 10 rules</h3><ol><li>Problems before products. Begin with what the customer needs.</li><li>Questions create sales.</li><li>Listen more than you speak.</li><li>Diagnose before you recommend.</li><li>Sell outcomes: confidence, speed, reliability, peace of mind.</li><li>Price reflects value. Never apologize for professional pricing.</li><li>Never argue. Ask another question.</li><li>Every conversation ends with a next step.</li><li>Relationships beat transactions.</li><li>Represent POTENT with pride. If we say we will, we do.</li></ol>\n<h3>Opening</h3><p>\"Hey, this is [NAME] with POTENT. How are you doing today? I'll keep it quick. Did I catch you with about 30 seconds?\" Then: \"We help businesses when freight needs to move quickly or their regular transportation cannot cover something. Out of curiosity, how are you handling those situations today?\" Then stop and listen.</p>\n<h3>Objections</h3><ul><li><b>\"We already have a carrier.\"</b> \"That makes sense. What happens when they are unavailable or something urgent comes up?\"</li><li><b>\"Send me information.\"</b> \"Absolutely. Before I do, what kind of transportation challenges does your company usually run into?\"</li><li><b>\"Your price is too high.\"</b> \"Is it higher than what you pay now, or higher than you expected?\" Then: \"How important is the delivery timeline?\"</li><li><b>\"I need to think about it.\"</b> \"Of course. Usually there is something specific. What is the biggest thing?\"</li></ul>\n<h3>Closing</h3><p>Problem: \"The biggest challenge is ___, correct?\" Impact: \"When that happens it creates ___ for your team, correct?\" Close: \"Based on everything we discussed, is there any reason we should not move forward?\" Then be quiet. Never end with \"let me know.\"</p>\n<h3>Daily standard</h3><div class=\"tbl\"><table><tr><td>New companies researched</td><td class=\"n\">25</td></tr><tr><td>Outbound calls</td><td class=\"n\">50</td></tr><tr><td>Personalized emails</td><td class=\"n\">25</td></tr><tr><td>Follow-ups completed</td><td class=\"n\">10</td></tr><tr><td>CRM updates</td><td class=\"n\">every interaction</td></tr></table></div>\n<h3>Working a lead</h3><ol class=\"steps\"><li>Open the Leads tab, filter Not Contacted.</li><li>Research the company for 30 seconds.</li><li>Tap the number, reach the decision maker.</li><li>Log the outcome right after the call: No Answer, Voicemail, Not Interested, Follow Up (date required), Interested, Booked.</li><li>Set a follow-up date on every warm lead.</li></ol>"},{"id":"os","title":"Selling POTENT OS","roles":["owner","dispatch","dispatcher"],"html":"<p>Ask first. Never pitch first. Make the problem real. Give one clear solution. End every message with a question.</p>\n<ul class=\"chk\"><li><b>S, Situation:</b> \"How many trucks do you run? What do you pay per truck per month for GPS and software today?\" Let them give you the number.</li><li><b>A, Amplify:</b> Do the math with THEIR number. Trucks × their fee × 12 × years.</li><li><b>K, Key solution:</b> \"POTENT OS. One-time license, works offline, no per-truck software fees, your data stays yours.\"</li><li><b>E, End with a question:</b> \"What are you paying per truck?\" \"What day works for a 15 minute call?\" Never end with \"let me know.\"</li></ul>\n<div class=\"note warn\"><b>Stay honest.</b> Do not say a competitor \"cuts you off\" or quote a competitor's price as fact. Use the prospect's own numbers and our published prices. If you do not know, say so and find out.</div><h3>Pick the plan by fleet size</h3><div class=\"tbl\"><table><tr><th>Plan</th><th>Fleet</th><th class=\"n\">One-time</th><th class=\"n\">Optional support</th></tr><tr><td>Starter</td><td>up to 10 trucks</td><td class=\"n\">$4,995</td><td class=\"n\">$149/mo</td></tr><tr><td>Growth</td><td>up to 50 trucks</td><td class=\"n\">$9,995</td><td class=\"n\">$249/mo</td></tr><tr><td>Fleet</td><td>up to 150 trucks</td><td class=\"n\">$19,995</td><td class=\"n\">$399/mo</td></tr><tr><td>Enterprise</td><td>up to 300 trucks</td><td class=\"n\">$34,995</td><td class=\"n\">$599/mo</td></tr></table></div><p class=\"small\">300+ trucks is a custom quote. Flex Pay on Fleet ($3,999 down + 12 × $1,333) and Enterprise ($6,999 down + 12 × $2,333), 0% interest. Use the calculator at os-guide.html with the prospect's own numbers.</p>\n<h3>Five things to lead with</h3><ul class=\"chk\"><li>Works 100% offline and installs like an app</li><li>Voice-activated quoting while on the phone</li><li>Profit Guard on every quote</li><li>Each company's data is completely separate and exportable</li><li>14 languages across the whole app</li></ul>\n<h3>Email flow</h3><ol class=\"steps\"><li>Cold email 1: one question, ends with \"What are you paying per truck per month? Reply with a number.\"</li><li>No reply: follow up on day 3, 7, 14 and 21. Never skip a touch.</li><li>They reply: send the full value email and offer a short call, same day.</li><li>They book: confirm and ask who else should be on the call.</li><li>On the call: ask, do the math with their numbers, then close and stop talking.</li></ol>\n<h3>Pipeline habits</h3><ul class=\"chk\"><li>Log every prospect. If it is not logged, it did not happen.</li><li>Set the next follow-up on every prospect.</li><li>Work the overdue (red) ones first every morning.</li></ul>"},{"id":"quiz","title":"Self-check quiz","roles":["owner","dispatch","dispatcher","driver"],"html":"<div id=\"quiz\"></div>"}],"quiz":[{"q":"What does a Local (0-50 mile) delivery cost, scheduled?","a":"$400","o":["$400","$750","$1500","$250"]},{"q":"How much less is a same-day zone job than scheduled?","a":"$25","o":["$25","$50","$100","Same price"]},{"q":"How much more is a Rush job?","a":"$100","o":["$100","$25","$50","$200"]},{"q":"What is the truck’s maximum cargo weight?","a":"4,500 lbs","o":["4,500 lbs","3,000 lbs","6,000 lbs","10,000 lbs"]},{"q":"What discount does cash get?","a":"10%","o":["10%","5%","15%","20%"]},{"q":"A driver sees more furniture than was booked. What do they do?","a":"Photograph it, report a scope difference, and wait for the office to authorize a new price","o":["Photograph it, report a scope difference, and wait for the office to authorize a new price","Raise the price themselves","Take it anyway for free","Leave without telling anyone"]},{"q":"What does a red Profit Guard card mean?","a":"The job is short of its share of the bills. Review before booking","o":["The job is short of its share of the bills. Review before booking","The customer is angry","The truck is full","Payment failed"]},{"q":"When must photos and measurements be collected?","a":"Before booking","o":["Before booking","After the job","Only for big jobs","Only if the customer asks"]},{"q":"What does a single item / minimum cost?","a":"$179","o":["$179","$99","$350","$500"]},{"q":"A vendor has not been verified in 30 days. Its status shows:","a":"NEEDS CONFIRMATION","o":["NEEDS CONFIRMATION","VERIFIED","INACTIVE","Deleted"]},{"q":"Which payments do we accept?","a":"Cash and card","o":["Cash and card","Cash, card and checks","Card only","Checks only"]},{"q":"What is the Starter plan price?","a":"$4,995 one-time","o":["$4,995 one-time","$9,995","$149 per month","$34,995"]}],"built":"October 8, 2026"};
function J(s, o) { return { statusCode: s, headers: { "Content-Type": "application/json", "Cache-Control": "no-store" }, body: JSON.stringify(o) }; }
function b64u(buf) { return Buffer.from(buf).toString("base64").replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, ""); }
function verify(token) {
    if (!token || typeof token !== "string" || token.indexOf(".") < 0) return null;
    var parts = token.split(".");
    var expect = b64u(crypto.createHmac("sha256", process.env.AUTH_SECRET).update(parts[0]).digest());
    var a = Buffer.from(parts[1] || ""), b = Buffer.from(expect);
    if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return null;
    try { var p = JSON.parse(Buffer.from(parts[0].replace(/-/g, "+").replace(/_/g, "/"), "base64").toString("utf8")); return p.exp && p.exp >= Date.now() ? p : null; } catch (e) { return null; }
}
exports.handler = async function (event) {
    if (!process.env.AUTH_SECRET) return J(500, { ok: false, error: "Server not configured" });
    var h = event.headers || {}; var tok = verify(String(h.authorization || h.Authorization || "").replace(/^Bearer\s+/i, ""));
    if (!tok) return J(401, { ok: false, error: "Sign in again" });
    if (tok.orgId) return J(403, { ok: false, error: "POTENT team only" });           // customer-company logins never see POTENT's internal pages
    if (["owner", "dispatch", "dispatcher", "driver"].indexOf(tok.role) < 0) return J(403, { ok: false, error: "Not allowed" });
    var page = (event.queryStringParameters || {}).page === "training" ? "training" : "team";
    var role = tok.role;
    var secs = CONTENT[page].filter(function (s) { return s.roles.indexOf(role) >= 0; });
    return J(200, { ok: true, role: role, built: CONTENT.built, sections: secs, quiz: CONTENT.quiz });
};
